(function(){const A=[{"id":"sp7-balzam-duhov","n":"Бальзам Духов","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «психический» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-slovo-mirazhey","n":"Слово Миражей","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 психический","cl":["Бард","Колдун"],"ds":"Вы произносите истинное слово (миражей). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (психический) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-oblik-sveta","n":"Облик Света","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 излучение","cl":["Паладин","Жрец","Следопыт"],"ds":"Вы принимаете облик (света): сопротивление урону «излучение» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (излучение). Попадание: цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Света","orig":true,"pack":"spells7.js"},{"id":"sp7-cep-shipov","n":"Цепь Шипов","l":2,"sc":"Преобразование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 колющий","cl":["Друид","Чародей","Колдун"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (колющий) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Сила) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Сила","atk":true,"mech":"Цепь","theme":"Шипов","orig":true,"pack":"spells7.js"},{"id":"sp7-iskra-run","n":"Искра Рун","l":0,"sc":"Ограждение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 силовое поле","cl":["Жрец","Изобретатель","Волшебник"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (силовое поле). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Рун","orig":true,"pack":"spells7.js"},{"id":"sp7-stena-vremeni","n":"Стена Времени","l":4,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 силовое поле","cl":["Бард","Чародей","Паладин"],"ds":"Стена (времени) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Мудрость): 5к8 урона (силовое поле) при провале (и цель замедляется: не может совершать бонусных действий до конца своего следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Мудрость","atk":false,"mech":"Стена","theme":"Времени","orig":true,"pack":"spells7.js"},{"id":"sp7-oruzhie-teni","n":"Оружие Тени","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 некротика","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (некротика). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Мудрость): при провале она окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Тени","orig":true,"pack":"spells7.js"},{"id":"sp7-vspyshka-krovi","n":"Вспышка Крови","l":0,"sc":"Некромантия","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 некротика","cl":["Жрец","Колдун","Чародей"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Телосложение), получая 1к6 урона (некротика) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Телосложение","atk":false,"mech":"Вспышка","theme":"Крови","orig":true,"pack":"spells7.js"},{"id":"sp7-proklyatie-molniy","n":"Проклятие Молний","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 электричество","cl":["Чародей","Друид","Волшебник"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (электричество), а в начале каждого её хода она бросает к4: на 1 она не может совершать реакции до начала своего следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Молний","orig":true,"pack":"spells7.js"},{"id":"sp7-slepok-groma","n":"Слепок Грома","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Маленький колокольчик.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы создаёте немагический предмет из звенящей бронзы размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Грома","orig":true,"pack":"spells7.js"},{"id":"sp7-maloe-chudo-ineya","n":"Малое Чудо Инея","l":0,"sc":"Воплощение","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Друид","Волшебник","Следопыт"],"ds":"Вы творите мелкое чудо: заморозить до 30 л воды, покрыть предмет узором инея или охладить пищу и питьё на 1 час. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Инея","orig":true,"pack":"spells7.js"},{"id":"sp7-legion-plameni","n":"Легион Пламени","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 огонь","cl":["Колдун","Следопыт","Волшебник"],"ds":"Появляются четыре духа (пламени): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «огонь». Каждый атакует заклинанием 1,5 м на 2к6 урона (огонь). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Пламени","orig":true,"pack":"spells7.js"},{"id":"sp7-strazh-kostey","n":"Страж Костей","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Вы призываете крошечного духа (костей): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (колющий)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Костей","orig":true,"pack":"spells7.js"},{"id":"sp7-obereg-pustoty","n":"Оберег Пустоты","l":0,"sc":"Вызов","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Волшебник","Паладин","Жрец"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «силовое поле», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Пустоты","orig":true,"pack":"spells7.js"},{"id":"sp7-svyatilische-zvezd","n":"Святилище Звёзд","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Изобретатель"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Мудрость) — при провале они очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Мудрость","atk":false,"mech":"Святилище","theme":"Звёзд","orig":true,"pack":"spells7.js"},{"id":"sp7-vzryv-razuma","n":"Взрыв Разума","l":3,"sc":"Очарование","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 психический","cl":["Чародей","Бард","Колдун"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Интеллект), получая 6к6 урона (психический) при провале (и цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Взрыв","theme":"Разума","orig":true,"pack":"spells7.js"},{"id":"sp7-volna-yada","n":"Волна Яда","l":1,"sc":"Преобразование","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 яд","cl":["Колдун","Изобретатель","Друид"],"ds":"Существа в конусе совершают спасбросок (Телосложение): при провале 2к6 урона (яд) и цель отравлена до конца своего следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Волна","theme":"Яда","orig":true,"pack":"spells7.js"},{"id":"sp7-svyaz-voln","n":"Связь Волн","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Жрец","Друид","Паладин"],"ds":"Вы вопрошаете водоём (вода помнит всё, что в неё упало), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Волн","orig":true,"pack":"spells7.js"},{"id":"sp7-kokon-vetra","n":"Кокон Ветра","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Чародей","Друид"],"ds":"Кокон (ветра) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Сила) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Кокон","theme":"Ветра","orig":true,"pack":"spells7.js"},{"id":"sp7-pokrov-kamnya","n":"Покров Камня","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Кусочек гранита.","d":"1 час","conc":false,"rit":false,"dmg":"5 дробящий","cl":["Изобретатель","Волшебник","Паладин"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (дробящий); у вас сопротивление урону «дробящий». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Камня","orig":true,"pack":"spells7.js"},{"id":"sp7-kolco-duhov","n":"Кольцо Духов","l":6,"sc":"Вызов","t":"1 действие","r":"45 м","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 психический","cl":["Бард","Колдун"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Мудрость): при провале оно получает 6к8 урона (психический), не проходит и испугана вами до конца её следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Мудрость","atk":false,"mech":"Кольцо","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-ubezhische-mirazhey","n":"Убежище Миражей","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Кусочек стекла.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Колдун","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: снаружи убежище выглядит как скала, руины или пустое место. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-chute-sveta","n":"Чутьё Света","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Жрец","Паладин","Друид"],"ds":"Вы чувствуете нежить, исчадий, освящённые и осквернённые места в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Света","orig":true,"pack":"spells7.js"},{"id":"sp7-katastrofa-shipov","n":"Катастрофа Шипов","l":7,"sc":"Преобразование","t":"1 действие","r":"300 м","c":"ВСМ","m":"Шип розы.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 колющий","cl":["Друид","Бард"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Сила) — 12к6 урона (колющий) при провале (и цель опутывается колючими лозами: скорость 0 до конца её следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Сила","atk":false,"mech":"Катастрофа","theme":"Шипов","orig":true,"pack":"spells7.js"},{"id":"sp7-opros-run","n":"Опрос Рун","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Резец и кусочек кости.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Жрец","Волшебник"],"ds":"Вы обращаетесь к стихии: вопрошаете надпись или руну (она рассказывает, кто её начертал и зачем). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Рун","orig":true,"pack":"spells7.js"},{"id":"sp7-shag-vremeni","n":"Шаг Времени","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Мудрость) или получает 1к6 урона (силовое поле). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Шаг","theme":"Времени","orig":true,"pack":"spells7.js"},{"id":"sp7-vlast-teni","n":"Власть Тени","l":8,"sc":"Иллюзия","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 некротика","cl":["Колдун","Волшебник"],"ds":"Вы повелеваете стихией (тени) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Мудрость), 6к10 урона (некротика) при провале и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м, половина при успехе.","save":"Мудрость","atk":false,"mech":"Власть","theme":"Тени","orig":true,"pack":"spells7.js"},{"id":"sp7-burya-krovi","n":"Буря Крови","l":4,"sc":"Некромантия","t":"1 действие","r":"90 м","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Буря (крови) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Телосложение): 3к6 урона (некротика) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Буря","theme":"Крови","orig":true,"pack":"spells7.js"},{"id":"sp7-sfera-molniy","n":"Сфера Молний","l":2,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 электричество","cl":["Чародей","Изобретатель","Волшебник"],"ds":"Сфера (молний) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Ловкость): 2к6 урона (электричество) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Ловкость","atk":false,"mech":"Сфера","theme":"Молний","orig":true,"pack":"spells7.js"},{"id":"sp7-apokalipsis-groma","n":"Апокалипсис Грома","l":9,"sc":"Воплощение","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 звук","cl":["Бард","Чародей"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Телосложение): 14к6 урона (звук) плюс 14к6 силовым полем при провале (и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Телосложение","atk":false,"mech":"Апокалипсис","theme":"Грома","orig":true,"pack":"spells7.js"},{"id":"sp7-vrata-ineya","n":"Врата Инея","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 холод","cl":["Чародей","Друид","Следопыт"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (инея). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (холод). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Инея","orig":true,"pack":"spells7.js"},{"id":"sp7-zavesa-plameni","n":"Завеса Пламени","l":2,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Следопыт"],"ds":"Куб с ребром 6 м заполняется завесой (пламени): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Ловкость) — при провале оно загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Ловкость","atk":false,"mech":"Завеса","theme":"Пламени","orig":true,"pack":"spells7.js"},{"id":"sp7-iskra-kostey","n":"Искра Костей","l":0,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 колющий","cl":["Жрец","Колдун","Волшебник"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (колющий). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Костей","orig":true,"pack":"spells7.js"},{"id":"sp7-stena-pustoty","n":"Стена Пустоты","l":4,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 силовое поле","cl":["Чародей","Колдун","Паладин"],"ds":"Стена (пустоты) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Харизма): 5к8 урона (силовое поле) при провале (и цель не может телепортироваться и перемещаться между планами до конца её следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Стена","theme":"Пустоты","orig":true,"pack":"spells7.js"},{"id":"sp7-oruzhie-zvezd","n":"Оружие Звёзд","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 излучение","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (излучение). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Мудрость): при провале она очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Звёзд","orig":true,"pack":"spells7.js"},{"id":"sp7-vspyshka-razuma","n":"Вспышка Разума","l":0,"sc":"Очарование","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 психический","cl":["Бард","Чародей","Колдун"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Интеллект), получая 1к6 урона (психический) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Интеллект","atk":false,"mech":"Вспышка","theme":"Разума","orig":true,"pack":"spells7.js"},{"id":"sp7-proklyatie-yada","n":"Проклятие Яда","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 яд","cl":["Следопыт","Колдун","Паладин"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (яд), а в начале каждого её хода она бросает к4: на 1 она отравлена до конца своего следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Яда","orig":true,"pack":"spells7.js"},{"id":"sp7-slepok-voln","n":"Слепок Волн","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Морская ракушка.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Друид","Паладин"],"ds":"Вы создаёте немагический предмет из воды, затвердевшей как стекло размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Волн","orig":true,"pack":"spells7.js"},{"id":"sp7-maloe-chudo-vetra","n":"Малое Чудо Ветра","l":0,"sc":"Воплощение","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы творите мелкое чудо: поднять порыв, гасящий свечи, разгоняющий туман в 3 м или уносящий лёгкий предмет. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Ветра","orig":true,"pack":"spells7.js"},{"id":"sp7-legion-kamnya","n":"Легион Камня","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Друид","Следопыт","Волшебник"],"ds":"Появляются четыре духа (камня): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «дробящий». Каждый атакует заклинанием 1,5 м на 2к6 урона (дробящий). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Камня","orig":true,"pack":"spells7.js"},{"id":"sp7-pechat-duhov","n":"Печать Духов","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Благовония.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 психический","cl":["Жрец","Паладин","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Мудрость): 3к6 урона (психический) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Печать","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-kope-mirazhey","n":"Копьё Миражей","l":1,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 психический","cl":["Бард","Колдун","Друид"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (психический). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-dvoynik-sveta","n":"Двойник Света","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 излучение","cl":["Паладин","Жрец","Бард"],"ds":"Вы создаёте двойника из застывшего света, яркого как свеча. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (излучение) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Света","orig":true,"pack":"spells7.js"},{"id":"sp7-potok-shipov","n":"Поток Шипов","l":3,"sc":"Преобразование","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 колющий","cl":["Друид","Чародей","Бард"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Сила): 7к6 урона (колющий) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Поток","theme":"Шипов","orig":true,"pack":"spells7.js"},{"id":"sp7-uzy-run","n":"Узы Рун","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 силовое поле","cl":["Жрец","Следопыт","Паладин"],"ds":"Узы (рун) охватывают существо: спасбросок (Интеллект) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (силовое поле) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Узы","theme":"Рун","orig":true,"pack":"spells7.js"},{"id":"sp7-raspad-vremeni","n":"Распад Времени","l":6,"sc":"Преобразование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 силовое поле","cl":["Бард","Чародей"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (силовое поле) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Времени","orig":true,"pack":"spells7.js"},{"id":"sp7-duh-teni","n":"Дух Тени","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 некротика","cl":["Следопыт","Колдун","Волшебник"],"ds":"Вы призываете духа (тени) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (некротика). Иммунитет к урону «некротика». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Тени","orig":true,"pack":"spells7.js"},{"id":"sp7-kleymo-krovi","n":"Клеймо Крови","l":1,"sc":"Некромантия","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (некротика), и цель совершает спасбросок (Телосложение) — при провале она не может восстанавливать хиты до конца своего следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Клеймо","theme":"Крови","orig":true,"pack":"spells7.js"},{"id":"sp7-avatar-molniy","n":"Аватар Молний","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 электричество","cl":["Чародей","Волшебник"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «электричество», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (электричество). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Молний","orig":true,"pack":"spells7.js"},{"id":"sp7-aura-groma","n":"Аура Грома","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Бард","Жрец","Друид"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «звук» и преимущество на спасброски от эффектов, из-за которых цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода. Враг, начинающий ход в ауре, совершает спасбросок (Телосложение) или получает 2к6 урона (звук). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Аура","theme":"Грома","orig":true,"pack":"spells7.js"},{"id":"sp7-golos-ineya","n":"Голос Инея","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Бард","Колдун"],"ds":"Ваш голос наполняется силой стихии (инея). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Инея","orig":true,"pack":"spells7.js"},{"id":"sp7-carstvo-plameni","n":"Царство Пламени","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Щепоть серы.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Волшебник"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (пламени) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Ловкость","atk":false,"mech":"Царство","theme":"Пламени","orig":true,"pack":"spells7.js"},{"id":"sp7-opros-kostey","n":"Опрос Костей","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Фаланга пальца.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Волшебник"],"ds":"Вы обращаетесь к стихии: вопрошаете кости (покойник отвечает, как умер). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Костей","orig":true,"pack":"spells7.js"},{"id":"sp7-shag-pustoty","n":"Шаг Пустоты","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 силовое поле","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Харизма) или получает 1к6 урона (силовое поле). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Харизма","atk":false,"mech":"Шаг","theme":"Пустоты","orig":true,"pack":"spells7.js"},{"id":"sp7-vlast-zvezd","n":"Власть Звёзд","l":8,"sc":"Прорицание","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 излучение","cl":["Бард","Жрец"],"ds":"Вы повелеваете стихией (звёзд) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Мудрость), 6к10 урона (излучение) при провале и цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода, половина при успехе.","save":"Мудрость","atk":false,"mech":"Власть","theme":"Звёзд","orig":true,"pack":"spells7.js"},{"id":"sp7-burya-razuma","n":"Буря Разума","l":4,"sc":"Очарование","t":"1 действие","r":"90 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 психический","cl":["Чародей","Бард","Колдун"],"ds":"Буря (разума) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Интеллект): 3к6 урона (психический) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Интеллект","atk":false,"mech":"Буря","theme":"Разума","orig":true,"pack":"spells7.js"},{"id":"sp7-sfera-yada","n":"Сфера Яда","l":2,"sc":"Преобразование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 яд","cl":["Колдун","Изобретатель","Друид"],"ds":"Сфера (яда) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Телосложение): 2к6 урона (яд) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Сфера","theme":"Яда","orig":true,"pack":"spells7.js"},{"id":"sp7-apokalipsis-voln","n":"Апокалипсис Волн","l":9,"sc":"Вызов","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 дробящий","cl":["Чародей","Друид"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Сила): 14к6 урона (дробящий) плюс 14к6 силовым полем при провале (и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Сила","atk":false,"mech":"Апокалипсис","theme":"Волн","orig":true,"pack":"spells7.js"},{"id":"sp7-vrata-vetra","n":"Врата Ветра","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 звук","cl":["Чародей","Следопыт","Друид"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (ветра). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (звук). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Ветра","orig":true,"pack":"spells7.js"},{"id":"sp7-zavesa-kamnya","n":"Завеса Камня","l":2,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Друид","Волшебник","Следопыт"],"ds":"Куб с ребром 6 м заполняется завесой (камня): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Сила) — при провале оно сбивается с ног, если она Большая или меньше. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Завеса","theme":"Камня","orig":true,"pack":"spells7.js"},{"id":"sp7-kasanie-duhov","n":"Касание Духов","l":0,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 психический","cl":["Жрец","Бард","Колдун"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (психический), и цель испугана вами до конца её следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-tropa-mirazhey","n":"Тропа Миражей","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек стекла.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"До 8 согласных существ отправляются в путь по миражу: группа идёт к видимому вдали образу и оказывается там. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-morok-sveta","n":"Морок Света","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Чародей"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Света","orig":true,"pack":"spells7.js"},{"id":"sp7-otmetina-shipov","n":"Отметина Шипов","l":0,"sc":"Преобразование","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 колющий","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Вы отмечаете существо знаком (шипов). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (колющий). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Шипов","orig":true,"pack":"spells7.js"},{"id":"sp7-kara-run","n":"Кара Рун","l":5,"sc":"Ограждение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 силовое поле","cl":["Изобретатель","Жрец","Волшебник"],"ds":"Одно существо совершает спасбросок (Интеллект): 8к8 урона (силовое поле) при провале (и цель получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Интеллект","atk":false,"mech":"Кара","theme":"Рун","orig":true,"pack":"spells7.js"},{"id":"sp7-strazh-vremeni","n":"Страж Времени","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 силовое поле","cl":["Волшебник","Друид","Следопыт"],"ds":"Вы призываете крошечного духа (времени): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (силовое поле)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Времени","orig":true,"pack":"spells7.js"},{"id":"sp7-obereg-teni","n":"Оберег Тени","l":0,"sc":"Иллюзия","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Волшебник","Паладин","Жрец"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «некротика», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Тени","orig":true,"pack":"spells7.js"},{"id":"sp7-svyatilische-krovi","n":"Святилище Крови","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Капля вашей крови.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Изобретатель"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Телосложение) — при провале они не может восстанавливать хиты до конца своего следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Телосложение","atk":false,"mech":"Святилище","theme":"Крови","orig":true,"pack":"spells7.js"},{"id":"sp7-vzryv-molniy","n":"Взрыв Молний","l":3,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 электричество","cl":["Чародей","Изобретатель","Друид"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Ловкость), получая 6к6 урона (электричество) при провале (и цель не может совершать реакции до начала своего следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Ловкость","atk":false,"mech":"Взрыв","theme":"Молний","orig":true,"pack":"spells7.js"},{"id":"sp7-raskatistaya-volna-groma","n":"Раскатистая Волна Грома","l":1,"sc":"Воплощение","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 звук","cl":["Бард","Чародей","Жрец"],"ds":"Существа в конусе совершают спасбросок (Телосложение): при провале 2к6 урона (звук) и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Волна","theme":"Грома","orig":true,"pack":"spells7.js"},{"id":"sp7-svyaz-ineya","n":"Связь Инея","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Друид","Паладин","Бард"],"ds":"Вы вопрошаете лёд или снег поблизости (он помнит следы и голоса за последнюю неделю), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Инея","orig":true,"pack":"spells7.js"},{"id":"sp7-kokon-plameni","n":"Кокон Пламени","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Следопыт"],"ds":"Кокон (пламени) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Ловкость) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Ловкость","atk":false,"mech":"Кокон","theme":"Пламени","orig":true,"pack":"spells7.js"},{"id":"sp7-uzy-kostey","n":"Узы Костей","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 колющий","cl":["Колдун","Жрец","Следопыт"],"ds":"Узы (костей) охватывают существо: спасбросок (Телосложение) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (колющий) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Узы","theme":"Костей","orig":true,"pack":"spells7.js"},{"id":"sp7-raspad-pustoty","n":"Распад Пустоты","l":6,"sc":"Вызов","t":"1 действие","r":"18 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 силовое поле","cl":["Чародей","Колдун"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (силовое поле) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Пустоты","orig":true,"pack":"spells7.js"},{"id":"sp7-duh-zvezd","n":"Дух Звёзд","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 излучение","cl":["Жрец","Друид","Волшебник"],"ds":"Вы призываете духа (звёзд) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (излучение). Иммунитет к урону «излучение». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Звёзд","orig":true,"pack":"spells7.js"},{"id":"sp7-kleymo-razuma","n":"Клеймо Разума","l":1,"sc":"Очарование","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (психический), и цель совершает спасбросок (Интеллект) — при провале она не может совершать реакции и совершает с помехой следующую проверку Интеллекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Клеймо","theme":"Разума","orig":true,"pack":"spells7.js"},{"id":"sp7-avatar-yada","n":"Аватар Яда","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 яд","cl":["Колдун","Друид"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «яд», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (яд). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Яда","orig":true,"pack":"spells7.js"},{"id":"sp7-aura-voln","n":"Аура Волн","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Жрец","Друид","Паладин"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «дробящий» и преимущество на спасброски от эффектов, из-за которых цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству. Враг, начинающий ход в ауре, совершает спасбросок (Сила) или получает 2к6 урона (дробящий). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Аура","theme":"Волн","orig":true,"pack":"spells7.js"},{"id":"sp7-golos-vetra","n":"Голос Ветра","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Бард","Колдун"],"ds":"Ваш голос наполняется силой стихии (ветра). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Ветра","orig":true,"pack":"spells7.js"},{"id":"sp7-carstvo-kamnya","n":"Царство Камня","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек гранита.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Друид","Волшебник"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (камня) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Сила","atk":false,"mech":"Царство","theme":"Камня","orig":true,"pack":"spells7.js"},{"id":"sp7-perenos-duhov","n":"Перенос Духов","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь с караваном духов на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-balzam-mirazhey","n":"Бальзам Миражей","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Бард","Друид","Следопыт"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «психический» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-slovo-sveta","n":"Слово Света","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 излучение","cl":["Жрец","Бард"],"ds":"Вы произносите истинное слово (света). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (излучение) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Света","orig":true,"pack":"spells7.js"},{"id":"sp7-oblik-shipov","n":"Облик Шипов","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 колющий","cl":["Следопыт","Друид","Паладин"],"ds":"Вы принимаете облик (шипов): сопротивление урону «колющий» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (колющий). Попадание: цель опутывается колючими лозами: скорость 0 до конца её следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Шипов","orig":true,"pack":"spells7.js"},{"id":"sp7-cep-run","n":"Цепь Рун","l":2,"sc":"Ограждение","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 силовое поле","cl":["Изобретатель","Жрец","Волшебник"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (силовое поле) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Интеллект) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":true,"mech":"Цепь","theme":"Рун","orig":true,"pack":"spells7.js"},{"id":"sp7-iskra-vremeni","n":"Искра Времени","l":0,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (силовое поле). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Времени","orig":true,"pack":"spells7.js"},{"id":"sp7-stena-teni","n":"Стена Тени","l":4,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 некротика","cl":["Следопыт","Колдун","Чародей"],"ds":"Стена (тени) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Мудрость): 5к8 урона (некротика) при провале (и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Мудрость","atk":false,"mech":"Стена","theme":"Тени","orig":true,"pack":"spells7.js"},{"id":"sp7-oruzhie-krovi","n":"Оружие Крови","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 некротика","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (некротика). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Телосложение): при провале она не может восстанавливать хиты до конца своего следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Крови","orig":true,"pack":"spells7.js"},{"id":"sp7-vspyshka-molniy","n":"Вспышка Молний","l":0,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 электричество","cl":["Изобретатель","Чародей","Друид"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Ловкость), получая 1к6 урона (электричество) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Ловкость","atk":false,"mech":"Вспышка","theme":"Молний","orig":true,"pack":"spells7.js"},{"id":"sp7-proklyatie-groma","n":"Проклятие Грома","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Чародей","Бард","Жрец"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (звук), а в начале каждого её хода она бросает к4: на 1 она отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Грома","orig":true,"pack":"spells7.js"},{"id":"sp7-slepok-ineya","n":"Слепок Инея","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кристалл льда.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Друид","Волшебник","Паладин"],"ds":"Вы создаёте немагический предмет из вечного льда, не тающего 1 час размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Инея","orig":true,"pack":"spells7.js"},{"id":"sp7-maloe-chudo-plameni","n":"Малое Чудо Пламени","l":0,"sc":"Воплощение","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Изобретатель","Волшебник"],"ds":"Вы творите мелкое чудо: зажечь или погасить свечу, факел или костёр в 9 м либо заставить огонь принять форму фигуры на 1 минуту. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Пламени","orig":true,"pack":"spells7.js"},{"id":"sp7-kara-kostey","n":"Кара Костей","l":5,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 колющий","cl":["Колдун","Жрец","Изобретатель"],"ds":"Одно существо совершает спасбросок (Телосложение): 8к8 урона (колющий) при провале (и цель становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Телосложение","atk":false,"mech":"Кара","theme":"Костей","orig":true,"pack":"spells7.js"},{"id":"sp7-strazh-pustoty","n":"Страж Пустоты","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 силовое поле","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы призываете крошечного духа (пустоты): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (силовое поле)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Пустоты","orig":true,"pack":"spells7.js"},{"id":"sp7-obereg-zvezd","n":"Оберег Звёзд","l":0,"sc":"Прорицание","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Волшебник","Паладин"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «излучение», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Звёзд","orig":true,"pack":"spells7.js"},{"id":"sp7-svyatilische-razuma","n":"Святилище Разума","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Интеллект) — при провале они не может совершать реакции и совершает с помехой следующую проверку Интеллекта и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Интеллект","atk":false,"mech":"Святилище","theme":"Разума","orig":true,"pack":"spells7.js"},{"id":"sp7-vzryv-yada","n":"Взрыв Яда","l":3,"sc":"Преобразование","t":"1 действие","r":"45 м","c":"ВСМ","m":"Жало пчелы.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 яд","cl":["Колдун","Изобретатель","Друид"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Телосложение), получая 6к6 урона (яд) при провале (и цель отравлена до конца своего следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Взрыв","theme":"Яда","orig":true,"pack":"spells7.js"},{"id":"sp7-volna-voln","n":"Волна Волн","l":1,"sc":"Вызов","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Существа в конусе совершают спасбросок (Сила): при провале 2к6 урона (дробящий) и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Волна","theme":"Волн","orig":true,"pack":"spells7.js"},{"id":"sp7-svyaz-vetra","n":"Связь Ветра","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Перо.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы вопрошаете ветер (он приносит слова, сказанные здесь за последние сутки), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Ветра","orig":true,"pack":"spells7.js"},{"id":"sp7-kokon-kamnya","n":"Кокон Камня","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Друид","Волшебник","Паладин"],"ds":"Кокон (камня) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Сила) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Кокон","theme":"Камня","orig":true,"pack":"spells7.js"},{"id":"sp7-pokrov-duhov","n":"Покров Духов","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Благовония.","d":"1 час","conc":false,"rit":false,"dmg":"5 психический","cl":["Жрец","Паладин","Изобретатель"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (психический); у вас сопротивление урону «психический». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-kolco-mirazhey","n":"Кольцо Миражей","l":6,"sc":"Иллюзия","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 психический","cl":["Бард","Колдун"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Интеллект): при провале оно получает 6к8 урона (психический), не проходит и видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Интеллект","atk":false,"mech":"Кольцо","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-ubezhische-sveta","n":"Убежище Света","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Святой символ.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Паладин","Жрец","Бард"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: сияющий купол: нежить и исчадия не могут войти, внутри яркий свет. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Света","orig":true,"pack":"spells7.js"},{"id":"sp7-chute-shipov","n":"Чутьё Шипов","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Бард"],"ds":"Вы чувствуете растения, отравленные травы и существ, скрывающихся в зарослях в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Шипов","orig":true,"pack":"spells7.js"},{"id":"sp7-katastrofa-run","n":"Катастрофа Рун","l":7,"sc":"Ограждение","t":"1 действие","r":"300 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 силовое поле","cl":["Жрец","Волшебник"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Интеллект) — 12к6 урона (силовое поле) при провале (и цель получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Интеллект","atk":false,"mech":"Катастрофа","theme":"Рун","orig":true,"pack":"spells7.js"},{"id":"sp7-opros-vremeni","n":"Опрос Времени","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Песчинка из песочных часов.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Бард","Волшебник"],"ds":"Вы обращаетесь к стихии: вопрошаете само мгновение: вы видите эту местность такой, какой она была час назад. Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Времени","orig":true,"pack":"spells7.js"},{"id":"sp7-shag-teni","n":"Шаг Тени","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 некротика","cl":["Следопыт","Колдун","Волшебник"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Мудрость) или получает 1к6 урона (некротика). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Шаг","theme":"Тени","orig":true,"pack":"spells7.js"},{"id":"sp7-vlast-krovi","n":"Власть Крови","l":8,"sc":"Некромантия","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 некротика","cl":["Чародей","Жрец"],"ds":"Вы повелеваете стихией (крови) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Телосложение), 6к10 урона (некротика) при провале и цель не может восстанавливать хиты до конца своего следующего хода, половина при успехе.","save":"Телосложение","atk":false,"mech":"Власть","theme":"Крови","orig":true,"pack":"spells7.js"},{"id":"sp7-burya-molniy","n":"Буря Молний","l":4,"sc":"Воплощение","t":"1 действие","r":"90 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 электричество","cl":["Чародей","Изобретатель","Друид"],"ds":"Буря (молний) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Ловкость): 3к6 урона (электричество) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Ловкость","atk":false,"mech":"Буря","theme":"Молний","orig":true,"pack":"spells7.js"},{"id":"sp7-sfera-groma","n":"Сфера Грома","l":2,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Чародей","Бард","Жрец"],"ds":"Сфера (грома) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Телосложение): 2к6 урона (звук) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Сфера","theme":"Грома","orig":true,"pack":"spells7.js"},{"id":"sp7-apokalipsis-ineya","n":"Апокалипсис Инея","l":9,"sc":"Воплощение","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 холод","cl":["Чародей","Друид"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Телосложение): 14к6 урона (холод) плюс 14к6 силовым полем при провале (и цель покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Телосложение","atk":false,"mech":"Апокалипсис","theme":"Инея","orig":true,"pack":"spells7.js"},{"id":"sp7-vrata-plameni","n":"Врата Пламени","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 огонь","cl":["Чародей","Колдун","Волшебник"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (пламени). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (огонь). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Пламени","orig":true,"pack":"spells7.js"},{"id":"sp7-cep-kostey","n":"Цепь Костей","l":2,"sc":"Некромантия","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (колющий) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Телосложение) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":true,"mech":"Цепь","theme":"Костей","orig":true,"pack":"spells7.js"},{"id":"sp7-iskra-pustoty","n":"Искра Пустоты","l":0,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (силовое поле). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Пустоты","orig":true,"pack":"spells7.js"},{"id":"sp7-stena-zvezd","n":"Стена Звёзд","l":4,"sc":"Прорицание","t":"1 действие","r":"36 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 излучение","cl":["Бард","Жрец","Волшебник"],"ds":"Стена (звёзд) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Мудрость): 5к8 урона (излучение) при провале (и цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Мудрость","atk":false,"mech":"Стена","theme":"Звёзд","orig":true,"pack":"spells7.js"},{"id":"sp7-oruzhie-razuma","n":"Оружие Разума","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 психический","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (психический). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Интеллект): при провале она не может совершать реакции и совершает с помехой следующую проверку Интеллекта. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Разума","orig":true,"pack":"spells7.js"},{"id":"sp7-vspyshka-yada","n":"Вспышка Яда","l":0,"sc":"Преобразование","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 яд","cl":["Изобретатель","Колдун","Друид"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Телосложение), получая 1к6 урона (яд) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Телосложение","atk":false,"mech":"Вспышка","theme":"Яда","orig":true,"pack":"spells7.js"},{"id":"sp7-proklyatie-voln","n":"Проклятие Волн","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (дробящий), а в начале каждого её хода она бросает к4: на 1 она промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Волн","orig":true,"pack":"spells7.js"},{"id":"sp7-slepok-vetra","n":"Слепок Ветра","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Перо.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы создаёте немагический предмет из сгущённого воздуха — прозрачного и упругого размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Ветра","orig":true,"pack":"spells7.js"},{"id":"sp7-maloe-chudo-kamnya","n":"Малое Чудо Камня","l":0,"sc":"Преобразование","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Друид","Волшебник"],"ds":"Вы творите мелкое чудо: придать камню размером до 30 см новую форму или выдавить на камне знак. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Камня","orig":true,"pack":"spells7.js"},{"id":"sp7-legion-duhov","n":"Легион Духов","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Колдун","Жрец","Следопыт"],"ds":"Появляются четыре духа (духов): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «психический». Каждый атакует заклинанием 1,5 м на 2к6 урона (психический). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-pechat-mirazhey","n":"Печать Миражей","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек стекла.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 психический","cl":["Паладин","Волшебник","Изобретатель"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Интеллект): 3к6 урона (психический) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":false,"mech":"Печать","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-kope-sveta","n":"Копьё Света","l":1,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 излучение","cl":["Жрец","Бард","Чародей"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (излучение). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Света","orig":true,"pack":"spells7.js"},{"id":"sp7-dvoynik-shipov","n":"Двойник Шипов","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 колющий","cl":["Следопыт","Друид","Паладин"],"ds":"Вы создаёте двойника из живого дерева, продолжающего расти. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (колющий) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Шипов","orig":true,"pack":"spells7.js"},{"id":"sp7-potok-run","n":"Поток Рун","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 силовое поле","cl":["Изобретатель","Жрец","Бард"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Интеллект): 7к6 урона (силовое поле) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Поток","theme":"Рун","orig":true,"pack":"spells7.js"},{"id":"sp7-uzy-vremeni","n":"Узы Времени","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 силовое поле","cl":["Бард","Следопыт","Паладин"],"ds":"Узы (времени) охватывают существо: спасбросок (Мудрость) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (силовое поле) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Узы","theme":"Времени","orig":true,"pack":"spells7.js"},{"id":"sp7-raspad-teni","n":"Распад Тени","l":6,"sc":"Иллюзия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 некротика","cl":["Колдун","Чародей"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (некротика) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Тени","orig":true,"pack":"spells7.js"},{"id":"sp7-duh-krovi","n":"Дух Крови","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 некротика","cl":["Колдун","Жрец","Следопыт"],"ds":"Вы призываете духа (крови) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (некротика). Иммунитет к урону «некротика». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Крови","orig":true,"pack":"spells7.js"},{"id":"sp7-kleymo-molniy","n":"Клеймо Молний","l":1,"sc":"Воплощение","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 электричество","cl":["Изобретатель","Следопыт","Паладин"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (электричество), и цель совершает спасбросок (Ловкость) — при провале она не может совершать реакции до начала своего следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Ловкость","atk":false,"mech":"Клеймо","theme":"Молний","orig":true,"pack":"spells7.js"},{"id":"sp7-avatar-groma","n":"Аватар Грома","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 звук","cl":["Чародей","Бард"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «звук», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (звук). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Грома","orig":true,"pack":"spells7.js"},{"id":"sp7-aura-ineya","n":"Аура Инея","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 холод","cl":["Друид","Паладин","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «холод» и преимущество на спасброски от эффектов, из-за которых цель покрывается коркой льда. Враг, начинающий ход в ауре, совершает спасбросок (Телосложение) или получает 2к6 урона (холод). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Аура","theme":"Инея","orig":true,"pack":"spells7.js"},{"id":"sp7-golos-plameni","n":"Голос Пламени","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Бард"],"ds":"Ваш голос наполняется силой стихии (пламени). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Пламени","orig":true,"pack":"spells7.js"},{"id":"sp7-katastrofa-kostey","n":"Катастрофа Костей","l":7,"sc":"Некромантия","t":"1 действие","r":"300 м","c":"ВСМ","m":"Фаланга пальца.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 колющий","cl":["Колдун","Жрец"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Телосложение) — 12к6 урона (колющий) при провале (и цель становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Телосложение","atk":false,"mech":"Катастрофа","theme":"Костей","orig":true,"pack":"spells7.js"},{"id":"sp7-opros-pustoty","n":"Опрос Пустоты","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Чёрная жемчужина.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Волшебник","Паладин"],"ds":"Вы обращаетесь к стихии: вопрошаете пустоту между мирами (она отвечает чужим голосом). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Пустоты","orig":true,"pack":"spells7.js"},{"id":"sp7-shag-zvezd","n":"Шаг Звёзд","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 излучение","cl":["Бард","Жрец","Друид"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Мудрость) или получает 1к6 урона (излучение). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Шаг","theme":"Звёзд","orig":true,"pack":"spells7.js"},{"id":"sp7-vlast-razuma","n":"Власть Разума","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 психический","cl":["Чародей","Бард"],"ds":"Вы повелеваете стихией (разума) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Интеллект), 6к10 урона (психический) при провале и цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта, половина при успехе.","save":"Интеллект","atk":false,"mech":"Власть","theme":"Разума","orig":true,"pack":"spells7.js"},{"id":"sp7-burya-yada","n":"Буря Яда","l":4,"sc":"Преобразование","t":"1 действие","r":"90 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 яд","cl":["Изобретатель","Колдун","Чародей"],"ds":"Буря (яда) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Телосложение): 3к6 урона (яд) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Буря","theme":"Яда","orig":true,"pack":"spells7.js"},{"id":"sp7-sfera-voln","n":"Сфера Волн","l":2,"sc":"Вызов","t":"1 действие","r":"18 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Сфера (волн) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Сила): 2к6 урона (дробящий) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Сфера","theme":"Волн","orig":true,"pack":"spells7.js"},{"id":"sp7-apokalipsis-vetra","n":"Апокалипсис Ветра","l":9,"sc":"Воплощение","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 звук","cl":["Чародей","Друид"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Сила): 14к6 урона (звук) плюс 14к6 силовым полем при провале (и цель отталкивается на 4,5 м в выбранном вами направлении), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Сила","atk":false,"mech":"Апокалипсис","theme":"Ветра","orig":true,"pack":"spells7.js"},{"id":"sp7-vrata-kamnya","n":"Врата Камня","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 дробящий","cl":["Чародей","Друид","Волшебник"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (камня). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (дробящий). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Камня","orig":true,"pack":"spells7.js"},{"id":"sp7-zavesa-duhov","n":"Завеса Духов","l":2,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Куб с ребром 6 м заполняется завесой (духов): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Мудрость) — при провале оно испугана вами до конца её следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Завеса","theme":"Духов","orig":true,"pack":"spells7.js"},{"id":"sp7-kasanie-mirazhey","n":"Касание Миражей","l":0,"sc":"Иллюзия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (психический), и цель видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Миражей","orig":true,"pack":"spells7.js"},{"id":"sp7-tropa-sveta","n":"Тропа Света","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Святой символ.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Паладин","Жрец","Следопыт"],"ds":"До 8 согласных существ отправляются в путь по лучу рассвета: группа переносится туда, куда падает первый солнечный луч. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Света","orig":true,"pack":"spells7.js"}];const D=window.DATA=window.DATA||{};D.spells=D.spells||[];const ids=new Set(D.spells.map(s=>s.id));A.forEach(s=>{if(!ids.has(s.id))D.spells.push(s)});})();
